#!/usr/bin/env bash
# Kiro CLI lifecycle-hook adapter shared by every Firstmate Kiro session.
#
# Every Firstmate registration reaches this script without depending on the
# folder Kiro runs the hook from or on launcher environment, because a session
# resumed with plain kiro-cli carries none of the launcher's FM_KIRO_* exports:
#   - Task hooks generated by bin/fm-kiro-lib.sh (the V3 project hook file in
#     the worker's workspace and the explicit V2 fallback's embedded agent)
#     name this script by absolute path with `--kiro-home <per-task KIRO_HOME>`.
#   - The tracked primary .kiro/hooks/fm-firstmate.json resolves this script
#     from the hook payload's `cwd`, the workspace whose .kiro/hooks declared
#     it, so the shared file carries no machine path and a linked task worktree
#     that inherits it runs its own copy, which fails primary scope.
#   - The explicit V2 primary agent names the launcher's absolute path.
# Kiro waits for each command hook (verified on kiro-cli 2.22.1).
#
# Worker/scout lifecycle, generation-bound to the current task incarnation:
#   UserPromptSubmit  -> busy kiro-hook
#   PreToolUse        -> native progress marker
#   PostToolUse       -> native progress marker
#   Stop              -> idle kiro-hook plus the guarded turn-ended notification
#
# Task binding: the per-task KIRO_HOME (--kiro-home, else the inherited
# KIRO_HOME) holds the isolated-home pointer whose token must match its
# agents/fm-turn-end.d registry entry before any state mutation; the workspace
# pointer is migration-only. An inherited FM_KIRO_TASK_ID or FM_KIRO_STATE must
# agree with that registry entry.
#
# Generation binding: the fm-spawn launch exports FM_KIRO_BUSY_GEN, the exact
# incarnation token, so fm-busy-event.sh rejects a late hook from an older
# incarnation after a relaunch arms a new generation. After each event that
# token wins, this process records `<generation> <session_id>` in
# KIRO_HOME/.fm-kiro-session. A process with no inherited generation - a
# conversation resumed with plain kiro-cli - borrows the recorded generation
# only when the payload's session_id matches that record. Kiro reloads
# .kiro/hooks files while a session runs, so the generation is never baked into
# a hook command: a relaunch rebuilds KIRO_HOME, which drops the record, and
# the new incarnation records its own session, so an older conversation still
# running without launcher environment changes nothing.
#
# Primary/secondmate registrations carry FM_KIRO_PRIMARY_HOOK=1:
#   SessionStart      -> session-start digest into context, endpoint publication
#   UserPromptSubmit  -> endpoint ensure, then the drained wake queue while this
#                        session owns the home lock; when the lock is free or its
#                        recorded pid is not a live harness, the SessionStart
#                        path instead, because Kiro fires SessionStart only for a
#                        conversation's first prompt and a resumed primary would
#                        otherwise never retake the lock
#   Stop              -> endpoint ensure, then the watcher re-arm backstop below
# Task-bound Stop hooks reach the same re-arm block after their task updates; it
# acts only in primary scope for the lock-owning session. The re-arm forks into
# its own session because bin/fm-watch-arm.sh waits for a whole watcher cycle
# while Kiro holds the turn end until every Stop hook exits.
#
# Usage: fm-kiro-turnend-hook.sh [--kiro-home <dir>]   (hook payload on stdin)
#
# Every path exits 0 and stays quiet unless a primary context hook deliberately
# writes context. A lifecycle writer refusal must never break Kiro's own turn.
set -u

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
FM_ROOT="${FM_ROOT_OVERRIDE:-$(cd "$SCRIPT_DIR/.." && pwd)}"
FM_HOME="${FM_HOME:-${FM_ROOT_OVERRIDE:-$FM_ROOT}}"
STATE="${FM_STATE_OVERRIDE:-$FM_HOME/state}"
GRACE=${FM_GUARD_GRACE:-300}
WATCH="$SCRIPT_DIR/fm-watch.sh"

# Isolated live-test probe: records arrival before payload parsing, scope checks,
# lock work, or endpoint publication. Only explicitly selected FM/KIRO/tmux
# fields are retained so credentials and unrelated process environment never
# enter the artifact.
if [ -n "${FM_KIRO_HOOK_PROBE_FILE:-}" ]; then
  {
    printf 'at=%s pid=%s ppid=%s pwd=%s\n' "$(date +%s)" "$$" "$PPID" "$PWD"
    env | LC_ALL=C grep -E '^(FM_(HOME|ROOT_OVERRIDE|STATE_OVERRIDE|KIRO_[A-Z0-9_]+)|KIRO_(HOME|DATA_DIR|CHAT_LOG_FILE|SESSION_ID|VERSION|CLI_ACP_CLIENT_NAME)|HOME|PWD|TMUX|TMUX_PANE|HERDR_ENV|HERDR_SESSION|HERDR_PANE_ID)=' \
      | LC_ALL=C sort
    printf '%s\n' --
  } >> "$FM_KIRO_HOOK_PROBE_FILE" 2>/dev/null || true
fi

KIRO_HOME_DIR=${KIRO_HOME:-}
while [ $# -gt 0 ]; do
  case "$1" in
    --kiro-home) KIRO_HOME_DIR=${2:-}; shift 2 2>/dev/null || shift ;;
    *) shift ;;
  esac
done
KIRO_HOME_DIR=${KIRO_HOME_DIR%/}

PAYLOAD=$(cat 2>/dev/null || true)
[ -n "$PAYLOAD" ] || exit 0
# Print the string value of the first top-level-shaped "<key>": "<value>" pair.
# Splitting on the quote character finds the key without jq; only a key is
# followed by a bare colon.
payload_field() {  # <key>
  printf '%s' "$PAYLOAD" | awk -v key="$1" '
    BEGIN { RS = "\"" }
    seen == 2 { print; exit }
    seen == 1 && $0 ~ /^[[:space:]]*:[[:space:]]*$/ { seen = 2; next }
    seen == 1 { seen = 0 }
    $0 == key { seen = 1 }
  '
}
EVENT=$(payload_field hook_event_name)
case "$EVENT" in
  agentSpawn|SessionStart) EVENT_KIND='session-start' ;;
  userPromptSubmit|UserPromptSubmit) EVENT_KIND=user-prompt-submit ;;
  preToolUse|PreToolUse) EVENT_KIND=pre-tool-use ;;
  postToolUse|PostToolUse) EVENT_KIND=post-tool-use ;;
  stop|agentStop|Stop|SessionEnd) EVENT_KIND=stop ;;
  *) exit 0 ;;
esac

kiro_primary_session_open() {
  local digest
  digest=$("$SCRIPT_DIR/fm-sessionstart-run.sh" --source startup 2>&1 || true)
  # shellcheck source=bin/fm-primary-endpoint-lib.sh
  . "$SCRIPT_DIR/fm-primary-endpoint-lib.sh"
  if fm_primary_endpoint_publish "$STATE" "$FM_ROOT" "$FM_HOME"; then
    digest="${digest}${digest:+$'\n'}KIRO_PRIMARY_ENDPOINT: structural wake doorbell published; the background watcher rings this pane for every actionable wake, so keep one cycle armed with bin/fm-watch-arm.sh and do not run foreground checkpoints."
  else
    digest="${digest}${digest:+$'\n'}KIRO_PRIMARY_ENDPOINT: structural wake doorbell unavailable ($FM_PRIMARY_ENDPOINT_ERROR); use the foreground checkpoint fallback."
  fi
  [ -z "$digest" ] || printf '%s\n' "$digest"
}

# Every-turn doorbell convergence for the lock-owning primary. Kiro fires
# SessionStart only for a conversation's first prompt, so the hooks that run on
# every turn keep the endpoint current (bin/fm-primary-endpoint-lib.sh owns the
# ensure contract). Local and cheap: no network and no digest. <announce>=1
# prints one context line only when this call (re)published, so the model learns
# a doorbell the startup digest reported unavailable is now live; a current
# record or a refusal stays silent.
kiro_primary_endpoint_ensure() {  # <announce>
  # shellcheck source=bin/fm-primary-endpoint-lib.sh
  . "$SCRIPT_DIR/fm-primary-endpoint-lib.sh"
  fm_primary_endpoint_ensure "$STATE" "$FM_ROOT" "$FM_HOME" || return 0
  [ "$1" = 1 ] && [ "$FM_PRIMARY_ENDPOINT_ENSURED" = published ] || return 0
  printf '%s\n' "KIRO_PRIMARY_ENDPOINT: structural wake doorbell published; the background watcher rings this pane for every actionable wake, so keep one cycle armed with bin/fm-watch-arm.sh and do not run foreground checkpoints."
}

# The tracked primary hook carries an explicit marker. A Firstmate worker
# worktree inherits the tracked .kiro/hooks file from the repository, but the
# shared primary-scope predicate makes that inherited invocation inert; its
# task-specific generated hook (without this marker) owns worker lifecycle.
if [ "${FM_KIRO_PRIMARY_HOOK:-0}" = 1 ]; then
  # A primary registration acts only for the checkout whose .kiro/hooks declared
  # it. An older tracked hook that reached another checkout's copy of this
  # script through a launcher variable names its own workspace in the payload.
  HOOK_WORKSPACE=$(payload_field cwd)
  if [ -n "$HOOK_WORKSPACE" ]; then
    [ "$(cd "$HOOK_WORKSPACE" 2>/dev/null && pwd -P)" = "$(cd "$FM_ROOT" 2>/dev/null && pwd -P)" ] || exit 0
  fi
  # shellcheck source=bin/fm-primary-scope-lib.sh
  . "$SCRIPT_DIR/fm-primary-scope-lib.sh"
  fm_primary_scope_matches "$FM_ROOT" "$STATE" || exit 0
  case "$EVENT_KIND" in
    session-start)
      kiro_primary_session_open
      exit 0
      ;;
    user-prompt-submit)
      # shellcheck source=bin/fm-session-lock-lib.sh
      . "$SCRIPT_DIR/fm-session-lock-lib.sh"
      if ! fm_session_lock_owned_by_self "$STATE"; then
        # bin/fm-lock.sh reclaims exactly a lock whose recorded pid is not a
        # live verified harness; a live owner or an unreadable lock stays put.
        fm_session_lock_inspect "$STATE"
        [ "$FM_LOCK_INSPECT_LIVE_HARNESS" != false ] || kiro_primary_session_open
        exit 0
      fi
      kiro_primary_endpoint_ensure 1
      # The queue remains durable until the model runs the exact
      # WAKE_ACK_REQUIRED command this drain prints after handling its context.
      [ -s "$STATE/.wake-queue" ] || exit 0
      "$SCRIPT_DIR/fm-wake-drain.sh" 2>&1 || true
      exit 0
      ;;
    pre-tool-use|post-tool-use)
      exit 0
      ;;
    stop)
      # Continue to the shared primary re-arm block below, but never run the
      # task-bound semantic writer from this static hook invocation.
      ;;
  esac
fi

KIRO_TASK_TURNEND=
KIRO_TASK_STATE=
KIRO_TASK_ID=
kiro_task_binding() {
  local auth_dir workspace pointer first token auth target base id state
  [ -n "$KIRO_HOME_DIR" ] || return 1
  auth_dir=$KIRO_HOME_DIR/agents/fm-turn-end.d
  [ -d "$auth_dir" ] && [ ! -L "$auth_dir" ] || return 1
  workspace=${KIRO_WORKSPACE_ROOT:-$PWD}
  pointer=$KIRO_HOME_DIR/.fm-kiro-turnend
  [ -e "$pointer" ] || [ -L "$pointer" ] || pointer=$workspace/.fm-kiro-turnend
  [ -f "$pointer" ] && [ ! -L "$pointer" ] || return 1
  first=
  IFS= read -r -n 256 first < "$pointer" 2>/dev/null || [ -n "$first" ] || return 1
  case "$first" in token=*) token=${first#token=} ;; *) return 1 ;; esac
  case "$token" in fm.????????????) : ;; *) return 1 ;; esac
  case "$token" in *[!A-Za-z0-9._-]*) return 1 ;; esac
  auth="$auth_dir/$token"
  [ -f "$auth" ] && [ ! -L "$auth" ] || return 1
  IFS= read -r target < "$auth" 2>/dev/null || return 1
  case "$target" in /*.turn-ended) : ;; *) return 1 ;; esac
  state=${target%/*}
  base=${target##*/}
  id=${base%.turn-ended}
  case "$id" in ''|*[!A-Za-z0-9._-]*) return 1 ;; esac
  [ -z "${FM_KIRO_TASK_ID:-}" ] || [ "$id" = "$FM_KIRO_TASK_ID" ] || return 1
  [ -z "${FM_KIRO_STATE:-}" ] || [ "$state" = "$FM_KIRO_STATE" ] || return 1
  KIRO_TASK_TURNEND=$target
  KIRO_TASK_STATE=$state
  KIRO_TASK_ID=$id
  return 0
}

KIRO_TASK_BOUND=0
if [ "${FM_KIRO_PRIMARY_HOOK:-0}" != 1 ] && kiro_task_binding; then
  KIRO_TASK_BOUND=1
fi

HOOK_SESSION_ID=$(payload_field session_id)
case "$HOOK_SESSION_ID" in
  *[!A-Za-z0-9._-]*) HOOK_SESSION_ID= ;;
esac
[ "${#HOOK_SESSION_ID}" -le 128 ] || HOOK_SESSION_ID=
KIRO_SESSION_RECORD=${KIRO_HOME_DIR:+$KIRO_HOME_DIR/.fm-kiro-session}

# Resolve the generation this invocation may write under, or return 1.
KIRO_GEN=
kiro_generation() {
  local recorded gen session
  if [ -n "${FM_KIRO_BUSY_GEN:-}" ]; then
    KIRO_GEN=$FM_KIRO_BUSY_GEN
    return 0
  fi
  [ -n "$HOOK_SESSION_ID" ] && [ -n "$KIRO_SESSION_RECORD" ] || return 1
  [ -f "$KIRO_SESSION_RECORD" ] && [ ! -L "$KIRO_SESSION_RECORD" ] || return 1
  IFS= read -r recorded < "$KIRO_SESSION_RECORD" 2>/dev/null || return 1
  case "$recorded" in ?*' '?*) ;; *) return 1 ;; esac
  gen=${recorded%% *}
  session=${recorded#* }
  [ -n "$gen" ] && [ "$session" = "$HOOK_SESSION_ID" ] || return 1
  KIRO_GEN=$gen
}

# Record the inherited generation's current session after fm-busy-event.sh
# accepted an event, so a later resume of this conversation can bind to it.
kiro_record_session() {
  local want current tmp
  [ -n "${FM_KIRO_BUSY_GEN:-}" ] && [ -n "$HOOK_SESSION_ID" ] && [ -n "$KIRO_SESSION_RECORD" ] || return 0
  want="$FM_KIRO_BUSY_GEN $HOOK_SESSION_ID"
  current=
  [ ! -f "$KIRO_SESSION_RECORD" ] || IFS= read -r current < "$KIRO_SESSION_RECORD" 2>/dev/null || true
  [ "$current" != "$want" ] || return 0
  tmp=$(mktemp "$KIRO_SESSION_RECORD.XXXXXX" 2>/dev/null) || return 0
  if printf '%s\n' "$want" > "$tmp" 2>/dev/null && mv -f -- "$tmp" "$KIRO_SESSION_RECORD" 2>/dev/null; then
    return 0
  fi
  rm -f -- "$tmp" 2>/dev/null || true
}

kiro_busy_apply() {  # <state> <event>
  [ "$KIRO_TASK_BOUND" = 1 ] || return 0
  kiro_generation || return 0
  "$SCRIPT_DIR/fm-busy-event.sh" apply "$KIRO_TASK_STATE" "$KIRO_TASK_ID" "$1" \
    --gen "$KIRO_GEN" --source kiro-hook --event "$2" \
    >/dev/null 2>&1 && kiro_record_session
}

kiro_busy_progress() {
  [ "$KIRO_TASK_BOUND" = 1 ] || return 0
  kiro_generation || return 0
  "$SCRIPT_DIR/fm-busy-event.sh" progress "$KIRO_TASK_STATE" "$KIRO_TASK_ID" \
    --gen "$KIRO_GEN" >/dev/null 2>&1 && kiro_record_session
}

case "$EVENT_KIND" in
  user-prompt-submit)
    kiro_busy_apply busy user-prompt-submit
    exit 0
    ;;
  pre-tool-use|post-tool-use)
    kiro_busy_progress
    exit 0
    ;;
  session-start)
    exit 0
    ;;
  stop)
    if [ "$KIRO_TASK_BOUND" = 1 ]; then
      touch "$KIRO_TASK_TURNEND" 2>/dev/null || true
      kiro_busy_apply idle stop
    fi
    ;;
esac

# Primary/secondmate Stop re-arm backstop. A worker's task-bound hook reaches
# this block too and stops at the lock-ownership check for its home.
# shellcheck source=bin/fm-primary-scope-lib.sh
. "$SCRIPT_DIR/fm-primary-scope-lib.sh"
fm_primary_scope_matches "$FM_ROOT" "$STATE" || exit 0

# shellcheck source=bin/fm-supervision-lib.sh
. "$SCRIPT_DIR/fm-supervision-lib.sh"
# shellcheck source=bin/fm-wake-lib.sh
. "$SCRIPT_DIR/fm-wake-lib.sh"
# shellcheck source=bin/fm-session-lock-lib.sh
. "$SCRIPT_DIR/fm-session-lock-lib.sh"

fm_session_lock_owned_by_self "$STATE" || exit 0
[ "${FM_KIRO_PRIMARY_HOOK:-0}" != 1 ] || kiro_primary_endpoint_ensure 0
[ -e "$STATE/.afk" ] && exit 0
fm_supervision_needed "$STATE" "$GRACE" || exit 0
fm_watcher_healthy "$STATE" "$WATCH" "$GRACE" "$FM_HOME" && exit 0

if command -v setsid >/dev/null 2>&1; then
  setsid --fork "$SCRIPT_DIR/fm-watch-arm.sh" </dev/null >/dev/null 2>&1 || true
fi

exit 0
